-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.shove_point(p_world uuid, p_x double precision, p_y double precision, p_fx double precision, p_fy double precision, p_by double precision, p_least double precision DEFAULT 1)
 RETURNS TABLE(x double precision, y double precision)
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_d double precision; v_go double precision; v_tx double precision; v_ty double precision; i int;
begin
  v_d := sqrt((p_x - p_fx) ^ 2 + (p_y - p_fy) ^ 2);
  if v_d < 0.001 then return; end if;
  v_go := case when p_by < 0 then -least(-p_by, greatest(0, v_d - p_least)) else p_by end;
  if abs(v_go) < 0.01 then return; end if;
  for i in reverse 4..1 loop
    v_tx := p_x + (p_x - p_fx) / v_d * v_go * i / 4;
    v_ty := p_y + (p_y - p_fy) / v_d * v_go * i / 4;
    if creature_tile_ok(p_world, floor(v_tx)::int, floor(v_ty)::int) and line_clear(p_world, p_x, p_y, v_tx, v_ty) then
      x := v_tx; y := v_ty; return next; return;
    end if;
  end loop;
end $function$
